//! Block damage (docs/BLOCK_DAMAGE.md, ADR 0072): blocks take several hits to break, by the tool
//! held, from each block's `damage` in its block data (`shared/blocks/*.json`, generated by
//! `shared/tools/gen.mjs` into `tools.gen.rs`). The server keeps a [`CellDamage`] per cell hit and
//! not yet broken ([`Damage`]), saved with the world in its own optional record.

use crate::bytes::{ByteReader, ByteWriter};
use crate::chopping::{BLOCK_DAMAGE, BREAK_TOOLS, BreakTool};
use crate::inventory::DropRule;
use std::collections::HashMap;

/// A block's hits to destroy (its `damage` in the block data).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct BlockDamageDef {
    pub block: &'static str,
    /// With bare hands or a tool not listed; none: it can't be broken so.
    pub default: Option<u32>,
    /// Per tool class (`pickaxe`, …) or item (`dwell:metal_pickaxe`), an item's over its class's.
    pub tools: &'static [(&'static str, u32)],
    /// How its damage is drawn (D2); none: not drawn.
    pub look: Option<DamageLook>,
    /// The chips a hit on it knocks out (the client's particles); none: none.
    pub chips: Option<crate::chopping::Chips>,
}

/// How a block's damage is drawn at each hit mark (`damage.look` in the block data).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DamageLookKind {
    /// An angular shard knocked off (stone).
    Shards,
    /// A roundish scoop (soils).
    Scoops,
    /// Small chips (wood).
    Chips,
}

/// A carved mark's height field (`damage.look.profile`, BLOCK_DAMAGE.md §6.2).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CarveProfile {
    /// A smooth bowl (soils' scoops), lit by smooth normals.
    Bowl,
    /// Angular facets round an off-centre apex, each lit flat.
    Facets,
    /// Spalled flakes (stone, WORK_QUEUE item 18: "stone doesn't dent, it shatters"): each hit
    /// chips out a few flat, shallow, elongated scars, stepped, lit flat and lighter (fresh rock).
    Spall,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct DamageLook {
    pub kind: DamageLookKind,
    /// A mark's width (cells) at full damage.
    pub size: f64,
    /// sRGB: the fresh face inside a mark.
    pub color: [u8; 3],
    /// sRGB: the cracks, growing with the damage.
    pub crack: [u8; 3],
    /// How deep a mark is shaded as cut into the face (cells; look only, its scoop's bowl or shard's
    /// facets; data `depth`, default 0.1).
    pub depth: f64,
    /// A scoop's per-pixel relief (BLOCK_DAMAGE.md §6.1): the loose soil raised round its rim (m;
    /// data `rim`, default 0.012).
    pub rim: f64,
    /// The steps the texture marches into the dent (0: lit only; the Low tier marches none; data
    /// `parallax`, default 6).
    pub parallax: u32,
    /// How much darker its damp floor is (0–1; data `darken`, default 0.35).
    pub darken: f64,
    /// The carved mesh's height field (data `profile`; default bowl for scoops, facets otherwise).
    pub profile: CarveProfile,
    /// A facet profile's facets round its apex (data `facets`, 3–8; default 5).
    pub facets: u32,
    /// A spall profile's flat chip-outs per hit, each smaller and deeper inside the last (data
    /// `flakes`, 1–4; default 2).
    pub flakes: u32,
    /// The dent's grid per side at most (data `grid`, 2–16; default 8).
    pub grid: u32,
    /// The cell's triangle budget for its carved faces (data `triangles`, 128–2048; default 256): the grid is
    /// coarsened until every struck face fits.
    pub triangles: u32,
    /// The crack overlay over the damaged cell's faces (BLOCK_DAMAGE.md §6.3; data `cracks`); none:
    /// no cracks.
    pub cracks: Option<Cracks>,
}

/// A block's crack overlay (`damage.look.cracks`, BLOCK_DAMAGE.md §6.3): its crack set's tiles
/// (`shared/textures/cracks.json`), the damage fraction each starts at, and how far it darkens.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Cracks {
    /// The set's atlas tiles in stage order, hairline to branching.
    pub tiles: &'static [&'static str],
    /// The damage fraction (0–1) each stage starts at, ascending, one a tile.
    pub stages: &'static [f64],
    /// How far a crack darkens the face (0–1; the tile multiplied over it).
    pub strength: f64,
    /// The width a crack tile covers round the hit (m; cracks.json `span`).
    pub span: f64,
}

impl Cracks {
    /// The crack stage (an index into `tiles`) at damage `fraction` (0–1): the last stage whose
    /// start it has reached; none below the first.
    pub fn stage(&self, fraction: f64) -> Option<usize> {
        self.stages.iter().rposition(|&s| fraction >= s)
    }
}

/// The damage look of a block, by name.
pub fn look_of(block: &str) -> Option<DamageLook> {
    BLOCK_DAMAGE
        .iter()
        .find(|d| d.block == block)
        .and_then(|d| d.look)
}

/// The hits to destroy `block` holding `held` (an item name; none: an empty hand), from tables
/// `damage` and `tools`: none when it can't be broken so (stone by hand). An item's own entry
/// wins; else its class's, divided by the item's tier speed (rounded up, at least 1); else the
/// block's default. A block without a `damage` entry breaks in one hit, as before.
pub fn hits_to_break_in(
    damage: &[BlockDamageDef],
    tools: &[BreakTool],
    block: &str,
    held: Option<&str>,
) -> Option<u32> {
    let Some(d) = damage.iter().find(|d| d.block == block) else {
        return Some(1);
    };
    let entry = |k: &str| d.tools.iter().find(|(t, _)| *t == k).map(|(_, n)| *n);
    if let Some(h) = held {
        if let Some(n) = entry(h) {
            return Some(n);
        }
        if let Some(t) = tools.iter().find(|t| t.item == h)
            && let Some(n) = entry(t.class)
        {
            return Some(((f64::from(n) / t.speed).ceil() as u32).max(1));
        }
    }
    d.default
}

/// [`hits_to_break_in`] over the build's data.
pub fn hits_to_break(block: &str, held: Option<&str>) -> Option<u32> {
    hits_to_break_in(BLOCK_DAMAGE, BREAK_TOOLS, block, held)
}

/// Whether `held` is a breaking tool (one of `tools.json`'s, the pickaxes, shovels and axes): an
/// empty hand, a block or any other item is not.
pub fn is_break_tool_in(tools: &[BreakTool], held: Option<&str>) -> bool {
    held.is_some_and(|h| tools.iter().any(|t| t.item == h))
}

/// The hits to destroy `block` holding `held` in a mode that does or doesn't allow
/// `instant_breaks` (`dwell_protocol::modes::Ability::InstantBreaks`; creative, owner
/// 2026-11-11: "I should be able to break any block while holding anything or nothing with the
/// exception of tools"): with it, anything but a breaking tool breaks every block in one hit; a
/// tool held keeps its hits. Without it, [`hits_to_break_in`].
pub fn hits_to_break_in_mode(
    damage: &[BlockDamageDef],
    tools: &[BreakTool],
    block: &str,
    held: Option<&str>,
    instant_breaks: bool,
) -> Option<u32> {
    if instant_breaks && !is_break_tool_in(tools, held) {
        return Some(1);
    }
    hits_to_break_in(damage, tools, block, held)
}

/// [`hits_to_break_in_mode`] over the build's data: the server and the client's prediction ask
/// this, so they agree.
pub fn hits_to_break_for(block: &str, held: Option<&str>, instant_breaks: bool) -> Option<u32> {
    hits_to_break_in_mode(BLOCK_DAMAGE, BREAK_TOOLS, block, held, instant_breaks)
}

/// How many of a block's `total` drops (of one item) hit `k` (1-based) of `hits` gives: half the
/// total (rounded down) spread over the hits before the last, so the hits' and the destroy's
/// ([`destroy_share`]) sum to `total` exactly.
pub fn hit_share(total: u32, hits: u32, k: u32) -> u32 {
    if hits <= 1 || k == 0 || k >= hits {
        return 0;
    }
    let half = total / 2;
    let over = hits - 1;
    k * half / over - (k - 1) * half / over
}

/// What the destroying hit gives of `total`: what the earlier hits ([`hit_share`]) did not.
pub fn destroy_share(total: u32, hits: u32) -> u32 {
    let given: u32 = (1..hits).map(|k| hit_share(total, hits, k)).sum();
    total - given
}

/// A block's certain drops: each rule that always drops one item, with its least count. The hits'
/// shares come from these; what is left of them, and every chance or ranged extra, drops on the
/// destroy.
pub fn certain_drops(rules: &[DropRule]) -> Vec<(&'static str, u32)> {
    rules
        .iter()
        .filter(|r| r.chance >= 1.0 && r.choices.len() == 1)
        .map(|r| (r.choices[0].item, u32::from(r.choices[0].min)))
        .collect()
}

/// The most hit marks a cell keeps (the newest; D2 draws them).
pub const MAX_HIT_MARKS: usize = 4;

/// Where a hit struck: the face (the edit's face index) and the point on it (each axis in
/// 1/255ths of the cell).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct HitMark {
    pub face: u8,
    pub point: [u8; 3],
}

/// A damaged cell: the state it was hit as (another state there now: the damage is gone), the hits
/// it has taken, and its newest hit marks.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct CellDamage {
    pub state: u16,
    pub hits: u16,
    /// The hits to break it by the tool of the last hit (its damage's fraction is `hits / need`).
    pub need: u16,
    pub marks: Vec<HitMark>,
}

impl CellDamage {
    /// What a client draws of it.
    pub fn view(&self) -> DamageView {
        let f = f64::from(self.hits) / f64::from(self.need.max(1));
        DamageView {
            fraction: (f.clamp(0.0, 1.0) * 255.0).round() as u8,
            marks: self.marks.clone(),
        }
    }
}

/// A damaged cell as a client draws it (`Damage` messages, the mesh job): how far it is to
/// breaking (0..255) and its hit marks.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct DamageView {
    pub fraction: u8,
    pub marks: Vec<HitMark>,
}

impl DamageView {
    pub fn write(&self, w: &mut ByteWriter) {
        w.u8(self.fraction);
        let n = self.marks.len().min(MAX_HIT_MARKS);
        w.u8(n as u8);
        for m in &self.marks[..n] {
            w.u8(m.face);
            for p in m.point {
                w.u8(p);
            }
        }
    }

    pub fn read(r: &mut ByteReader) -> DamageView {
        let fraction = r.u8();
        let n = usize::from(r.u8());
        r.check(n <= MAX_HIT_MARKS);
        let marks = (0..n.min(MAX_HIT_MARKS))
            .map(|_| HitMark {
                face: r.u8(),
                point: [r.u8(), r.u8(), r.u8()],
            })
            .collect();
        DamageView { fraction, marks }
    }
}

/// The damaged cells of a world.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Damage {
    pub cells: HashMap<[i32; 3], CellDamage>,
}

/// The save record's version.
const DAMAGE_VERSION: u8 = 1;

impl Damage {
    /// The hits `cell`, now `state`, has taken (0 when it holds another state than it was hit as).
    pub fn hits(&self, cell: [i32; 3], state: u16) -> u16 {
        self.cells
            .get(&cell)
            .filter(|d| d.state == state)
            .map_or(0, |d| d.hits)
    }

    /// Records a hit on `cell` (now `state`) at `mark`, by a tool that breaks it in `need`; the hits
    /// it has taken now.
    pub fn hit(&mut self, cell: [i32; 3], state: u16, need: u16, mark: HitMark) -> u16 {
        let d = self.cells.entry(cell).or_insert(CellDamage {
            state,
            hits: 0,
            need,
            marks: Vec::new(),
        });
        if d.state != state {
            *d = CellDamage {
                state,
                hits: 0,
                need,
                marks: Vec::new(),
            };
        }
        d.need = need;
        d.hits = d.hits.saturating_add(1);
        d.marks.push(mark);
        if d.marks.len() > MAX_HIT_MARKS {
            d.marks.remove(0);
        }
        d.hits
    }

    /// Forgets a cell's damage (it broke or was replaced).
    pub fn clear(&mut self, cell: [i32; 3]) {
        self.cells.remove(&cell);
    }

    /// The cells in a stable order (saves and messages).
    pub fn sorted(&self) -> Vec<([i32; 3], &CellDamage)> {
        let mut v: Vec<_> = self.cells.iter().map(|(&c, d)| (c, d)).collect();
        v.sort_by_key(|(c, _)| *c);
        v
    }

    pub fn to_bytes(&self) -> Vec<u8> {
        let mut out = Vec::new();
        let mut w = ByteWriter::new(&mut out);
        w.u8(DAMAGE_VERSION);
        let all = self.sorted();
        w.u32(all.len() as u32);
        for (c, d) in all {
            for v in c {
                w.i32(v);
            }
            w.u16(d.state);
            w.u16(d.hits);
            w.u16(d.need);
            w.u8(d.marks.len() as u8);
            for m in &d.marks {
                w.u8(m.face);
                for p in m.point {
                    w.u8(p);
                }
            }
        }
        out
    }

    /// A saved record; none when it is not one this build reads (a newer one's: kept, not written over).
    pub fn from_bytes(bytes: &[u8]) -> Option<Damage> {
        let mut r = ByteReader::new(bytes);
        if r.u8() != DAMAGE_VERSION {
            return None;
        }
        let n = r.u32() as usize;
        let mut cells = HashMap::new();
        // Each cell is at least 19 bytes: a corrupt count can't allocate past the record.
        for _ in 0..n.min(bytes.len() / 19 + 1) {
            let c = [r.i32(), r.i32(), r.i32()];
            let state = r.u16();
            let hits = r.u16();
            let need = r.u16();
            let k = usize::from(r.u8()).min(MAX_HIT_MARKS);
            let marks = (0..k)
                .map(|_| HitMark {
                    face: r.u8(),
                    point: [r.u8(), r.u8(), r.u8()],
                })
                .collect();
            cells.insert(
                c,
                CellDamage {
                    state,
                    hits,
                    need,
                    marks,
                },
            );
        }
        (r.ok() && r.at_end()).then_some(Damage { cells })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn hits_per_tool_tier_and_default_come_from_the_data() {
        // Owner, 2026-11-10: the right tool at stone tier about 5, metal about 3, the wrong tool or
        // bare hands about 10–12; bare hands can't break stone.
        assert_eq!(
            hits_to_break("dwell:stone", Some("dwell:stone_pickaxe")),
            Some(5)
        );
        assert_eq!(
            hits_to_break("dwell:stone", Some("dwell:metal_pickaxe")),
            Some(3)
        );
        assert_eq!(hits_to_break("dwell:stone", None), None);
        assert_eq!(
            hits_to_break("dwell:stone", Some("dwell:metal_shovel")),
            None
        );
        assert_eq!(
            hits_to_break("dwell:dirt", Some("dwell:wooden_shovel")),
            Some(5)
        );
        assert_eq!(
            hits_to_break("dwell:sand", Some("dwell:metal_shovel")),
            Some(3)
        );
        assert_eq!(hits_to_break("dwell:grass", None), Some(11));
        assert_eq!(
            hits_to_break("dwell:dirt", Some("dwell:stone_pickaxe")),
            Some(11)
        );
        // A block without `damage` breaks in one hit, as before.
        assert_eq!(hits_to_break("dwell:leaves", None), Some(1));
    }

    #[test]
    fn with_instant_breaks_anything_but_a_tool_breaks_any_block_in_one_hit() {
        // Owner, 2026-11-11 (creative): "I should be able to break any block while holding
        // anything or nothing with the exception of tools."
        for held in [None, Some("dwell:dirt"), Some("dwell:torch")] {
            assert_eq!(
                hits_to_break_for("dwell:stone", held, true),
                Some(1),
                "{held:?}"
            );
            assert_eq!(
                hits_to_break_for("dwell:dirt", held, true),
                Some(1),
                "{held:?}"
            );
        }
        // A tool keeps its hits, and its "can't" (a shovel on stone).
        assert_eq!(
            hits_to_break_for("dwell:stone", Some("dwell:stone_pickaxe"), true),
            Some(5)
        );
        assert_eq!(
            hits_to_break_for("dwell:stone", Some("dwell:metal_shovel"), true),
            None
        );
        // Without it (adventure), as the data says: bare hands can't break stone.
        assert_eq!(hits_to_break_for("dwell:stone", None, false), None);
        assert_eq!(hits_to_break_for("dwell:dirt", None, false), Some(11));
        // And the modes' data gives it to creative only.
        use crate::modes::{Ability, mode};
        assert!(mode("creative").unwrap().allows(Ability::InstantBreaks));
        assert!(!mode("adventure").unwrap().allows(Ability::InstantBreaks));
    }

    #[test]
    fn a_fixture_block_and_tool_by_data_alone() {
        let damage = [BlockDamageDef {
            block: "test:clay",
            default: Some(9),
            tools: &[("trowel", 6), ("test:golden_trowel", 1)],
            look: None,
            chips: None,
        }];
        let tools = [
            BreakTool {
                item: "test:trowel",
                class: "trowel",
                tier: "stone",
                speed: 2.0,
                contact_s: 0.0,
            },
            BreakTool {
                item: "test:golden_trowel",
                class: "trowel",
                tier: "metal",
                speed: 2.5,
                contact_s: 0.0,
            },
        ];
        let h = |held| hits_to_break_in(&damage, &tools, "test:clay", held);
        assert_eq!(h(Some("test:trowel")), Some(3), "class over tier speed");
        assert_eq!(h(Some("test:golden_trowel")), Some(1), "item over class");
        assert_eq!(h(None), Some(9));
        assert_eq!(h(Some("test:stick")), Some(9));
    }

    #[test]
    fn per_hit_and_destroy_drops_total_the_blocks_drops() {
        for total in 0..12 {
            for hits in 1..14 {
                let on_hits: u32 = (1..hits).map(|k| hit_share(total, hits, k)).sum();
                assert_eq!(
                    on_hits,
                    total / 2 * u32::from(hits > 1),
                    "{total} over {hits}"
                );
                assert_eq!(on_hits + destroy_share(total, hits), total);
            }
        }
        // Four over five hits: one a hit before the last.
        assert_eq!(
            (1..5).map(|k| hit_share(8, 5, k)).collect::<Vec<_>>(),
            [1, 1, 1, 1]
        );
    }

    #[test]
    fn damage_saves_and_loads_and_a_new_state_is_undamaged() {
        let mut d = Damage::default();
        for i in 0..6 {
            d.hit(
                [1, -2, 3],
                7,
                5,
                HitMark {
                    face: 2,
                    point: [i, 128, 255],
                },
            );
        }
        assert_eq!(d.hits([1, -2, 3], 7), 6);
        assert_eq!(d.cells[&[1, -2, 3]].view().fraction, 255, "6 of 5: full");
        assert_eq!(d.cells[&[1, -2, 3]].marks.len(), MAX_HIT_MARKS);
        assert_eq!(d.hits([1, -2, 3], 8), 0, "replaced: undamaged");
        let back = Damage::from_bytes(&d.to_bytes()).expect("reads its own record");
        assert_eq!(back, d);
        assert_eq!(Damage::from_bytes(&[9, 0, 0, 0, 0]), None, "a newer record");
        assert_eq!(
            d.hit(
                [1, -2, 3],
                8,
                5,
                HitMark {
                    face: 0,
                    point: [0; 3]
                }
            ),
            1
        );
    }
}
